import math
def max_Prime_Factors(num):
    factors = []
    # Divide num by 2 until it's odd
    while num % 2 == 0:
        factors.append(2)
        num //= 2
    # Check for odd factors starting from 3
    for i in range(3, int(math.sqrt(num)) + 1, 2):
        while num % i == 0:
            factors.append(i)
            num //= i
    # If num is a prime number greater than 2
    if num > 2:
        factors.append(num)
    return max(factors)

