def max_len_sub(arr,n):
  dp = deque()
  dp.append(arr[0])
  max_length = 1
  for i in range(1,n):
    if arr[i] > dp[-1]:
      dp.append(arr[i])
      max_length += 1
    else:
      while dp and dp[-1] < arr[i]:
        dp.pop()
      dp.append(arr[i])
      max_length = max(max_length,len(dp))
  return max_length

