  decreasing = []
  max_sum = 0

  # Find the longest increasing subsequence
  for i in range(n):
    while increasing and arr[i] > increasing[-1][0]:
      max_sum += increasing.pop()[1]
    increasing.append((arr[i],max_sum))

  # Find the longest decreasing subsequence
  for i in range(n-1,-1,-1):
    while decreasing and arr[i] > decreasing[-1][0]:
      max_sum += decreasing.pop()[1]
    decreasing.append((arr[i],max_sum))

